using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B4PolishAudit {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B4_LayoutPolish/";static string O=>R+"/Docs/Review/2026-11-09_B4_LayoutPolish/";static float[] V(Vector3 p)=>new[]{p.x,p.y,p.z};
 public static object Run(){var s=SceneManager.GetActiveScene();var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var ls=ts.Select(t=>t.GetComponent<Light>()).Where(l=>l).ToArray();var lights=JArray.Parse(File.ReadAllText(H+"lights_before.json"));var lightDiff=new List<string>();foreach(var j in lights){string id=(string)j["id"];var l=ls.FirstOrDefault(l=>GlobalObjectId.GetGlobalObjectIdSlow(l).ToString()==id);if(!l){lightDiff.Add("Missing "+id);continue;}var oldp=j["p"].Select(v=>(float)v).ToArray();if(Vector3.Distance(l.transform.position,new Vector3(oldp[0],oldp[1],oldp[2]))>.001f||Mathf.Abs(l.intensity-(float)j["intensity"])>.00001f||Mathf.Abs(l.range-(float)j["range"])>.00001f||Mathf.Abs(l.spotAngle-(float)j["spotAngle"])>.00001f)lightDiff.Add(l.name);}
 var active=ts.Where(t=>t.gameObject.activeInHierarchy).ToArray();var newRoots=active.Where(t=>PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject)&&PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject).Contains("/BP_")).ToArray();var meshAudit=new List<object>();foreach(var f in Directory.GetFiles("Assets/Afrer_Seconds/05.Model/Props/B4/","BP_*.fbx")){var g=AssetDatabase.LoadAssetAtPath<GameObject>(f.Replace('\\','/'));int deg=0,invalid=0,tris=0;foreach(var mf in g.GetComponentsInChildren<MeshFilter>()){var m=mf.sharedMesh;var vs=m.vertices;var ix=m.triangles;tris+=ix.Length/3;invalid+=vs.Count(v=>float.IsNaN(v.x)||float.IsInfinity(v.x)||float.IsNaN(v.y)||float.IsNaN(v.z));for(int i=0;i<ix.Length;i+=3)if(Vector3.Cross(vs[ix[i+1]]-vs[ix[i]],vs[ix[i+2]]-vs[ix[i]]).sqrMagnitude<1e-16f)deg++;}meshAudit.Add(new{asset=f,triangles=tris,degenerate=deg,invalid,missingMaterials=g.GetComponentsInChildren<Renderer>().Sum(r=>r.sharedMaterials.Count(m=>!m))});}
 var result=new{scene=s.path,dirty=s.isDirty,playing=Application.isPlaying,newActiveAssemblies=newRoots.Length,wallSafety=newRoots.Count(t=>t.name.Contains("WallSafety")),standaloneSafetyActive=active.Count(t=>t.name.Contains("SafetyEquipment")&&PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject)),lights=ls.Length,lightDiff,nonAscii=active.Where(t=>t.name.Any(c=>c>127)).Select(t=>t.name),missingMeshes=active.Select(t=>t.GetComponent<MeshFilter>()).Count(m=>m&&!m.sharedMesh),missingMaterials=active.Select(t=>t.GetComponent<Renderer>()).Where(r=>r).Sum(r=>r.sharedMaterials.Count(m=>!m)),meshAudit};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));File.WriteAllText(H+"final_instances.json",JsonConvert.SerializeObject(newRoots.Select(t=>new{name=t.name,asset=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject),p=V(t.position),e=V(t.eulerAngles),local=V(t.localPosition),parent=t.parent.name}),Formatting.Indented));return result;}
 static void Shot(string file,Vector3 pos,Vector3 target,float fov){var g=new GameObject("PolishAuditCamera"){hideFlags=HideFlags.HideAndDontSave};var c=g.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.nearClipPlane=.03f;c.farClipPlane=300;c.fieldOfView=fov;c.useOcclusionCulling=false;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,1000,24){antiAliasing=4};var prev=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,1000),0,0);tex.Apply();File.WriteAllBytes(O+file+".png",tex.EncodeToPNG());}finally{RenderTexture.active=prev;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
 public static object Details(){var s=SceneManager.GetActiveScene();var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).ToArray();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool active=player.activeSelf;player.SetActive(false);int count=0;try{foreach(var t in ts.Where(t=>t.name.Contains("WallSafety")&&PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject))){Shot(t.name+"_front",t.TransformPoint(new Vector3(.45f,1.55f,2.4f)),t.TransformPoint(new Vector3(0,1.19f,.1f)),67);Shot(t.name+"_mount",t.TransformPoint(new Vector3(1.2f,1.65f,1.0f)),t.TransformPoint(new Vector3(0,1.19f,0)),78);count+=2;}foreach(var t in ts.Where(t=>t.name.Contains("CalibrationIsland")&&PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject))){Shot(t.name+"_detail",t.TransformPoint(new Vector3(2.4f,1.9f,2.6f)),t.TransformPoint(new Vector3(0,1.0f,0)),78);count++;}foreach(string name in new[]{"B4_C04_AnalysisBench_02","B4_E02_ResearchDesk_01","B4_C03_InstrumentServiceBay_01"}){var t=ts.FirstOrDefault(t=>t.name==name);if(t){Shot(name+"_detail",t.TransformPoint(new Vector3(-1.7f,1.5f,2.0f)),t.TransformPoint(new Vector3(0,.85f,0)),75);count++;}}}finally{player.SetActive(active);EditorSceneManager.OpenScene(s.path);}return new{images=count};}
}
